const joystick=$('joystick'),stick=$('stick');let joyPointer=null;
function moveStick(e){if(e.pointerId!==joyPointer)return;const r=joystick.getBoundingClientRect(),dx=e.clientX-r.left-r.width/2,dy=e.clientY-r.top-r.height/2,max=r.width*.32,len=Math.hypot(dx,dy),scale=len>max?max/len:1;stick.style.transform=`translate(${dx*scale}px,${dy*scale}px)`;joystickInput.x=len<7?0:dx*scale/max;joystickInput.z=len<7?0:dy*scale/max;}
joystick.addEventListener('pointerdown',e=>{e.preventDefault();if(joyPointer!==null)return;joyPointer=e.pointerId;joystick.setPointerCapture(e.pointerId);wakeAudio();moveStick(e)});
joystick.addEventListener('pointermove',moveStick);
function releaseStick(e){if(e.pointerId!==joyPointer)return;joyPointer=null;joystickInput.x=joystickInput.z=0;stick.style.transform='';}
for(const name of ['pointerup','pointercancel','lostpointercapture'])joystick.addEventListener(name,releaseStick);
document.addEventListener('contextmenu',e=>e.preventDefault());document.addEventListener('selectstart',e=>e.preventDefault());
addEventListener('blur',()=>{joyPointer=null;joystickInput.x=joystickInput.z=0;stick.style.transform=''});
document.querySelectorAll('[data-key]').forEach(b=>b.addEventListener('lostpointercapture',()=>keys[b.dataset.key]=false));
